-- Read-only annual record summary. Separate ledgers are never treated as tax or accounting conclusions.
begin;
create or replace function public.list_verified_year_end_records(p_year integer)returns table(month_number integer,completed_load_count bigint,completed_rate_cents bigint,missing_rate_load_count bigint,invoiced_cents bigint,payments_received_cents bigint,operating_expense_cents bigint,fuel_ledger_cents bigint,payroll_approved_cents bigint,payroll_paid_cents bigint)
language plpgsql stable security definer set search_path=public as $$declare c uuid:=public.document_intake_company_id();r text:=public.current_business_role();d date;z date;begin if c is null or auth.uid()is null or r not in('super_admin','owner','accounting')then raise exception'Not authorized';end if;if p_year not between 2000 and extract(year from current_date)::integer+1 then raise exception'Invalid reporting year';end if;d:=make_date(p_year,1,1);z:=make_date(p_year+1,1,1);return query with months as(select generate_series(1,12)::integer m),completed as(select extract(month from e.event_at)::integer m,count(*)::bigint loads,coalesce(sum(f.rate_cents)filter(where f.rate_cents is not null),0)::bigint rates,count(*)filter(where f.rate_cents is null)::bigint missing from public.loads l join lateral(select x.event_at from public.load_events x where x.company_id=l.company_id and x.load_id=l.id and x.event_type='status_changed'and x.status in('delivered','closed')order by x.event_at desc limit 1)e on e.event_at>=d and e.event_at<z left join public.load_financials f on f.company_id=l.company_id and f.load_id=l.id where l.company_id=c and l.status in('delivered','closed')group by 1),invoices as(select extract(month from f.invoice_issued_at)::integer m,coalesce(sum(f.rate_cents),0)::bigint amount from public.load_financials f where f.company_id=c and f.invoice_issued_at>=d and f.invoice_issued_at<z and f.invoice_number is not null group by 1),payments as(select extract(month from p.paid_at)::integer m,sum(p.amount_cents)::bigint amount from public.load_payments p where p.company_id=c and p.paid_at>=d and p.paid_at<z group by 1),expenses as(select extract(month from e.incurred_on)::integer m,sum(e.amount_cents)::bigint amount from public.operating_expenses e where e.company_id=c and e.status='active'and e.incurred_on>=d and e.incurred_on<z group by 1),fuel as(select extract(month from f.purchased_at)::integer m,sum(f.total_cost_cents)::bigint amount from public.fuel_purchase_records f where f.company_id=c and f.status='active'and f.purchased_at>=d and f.purchased_at<z group by 1),payroll_approved as(select extract(month from s.period_end)::integer m,sum(s.net_pay_cents)::bigint amount from public.driver_settlements s where s.company_id=c and s.period_end>=d and s.period_end<z group by 1),payroll_paid as(select extract(month from s.paid_at)::integer m,sum(s.net_pay_cents)::bigint amount from public.driver_settlements s where s.company_id=c and s.status='paid'and s.paid_at>=d and s.paid_at<z group by 1)select m.m,coalesce(x.loads,0),coalesce(x.rates,0),coalesce(x.missing,0),coalesce(i.amount,0),coalesce(p.amount,0),coalesce(e.amount,0),coalesce(f.amount,0),coalesce(a.amount,0),coalesce(q.amount,0)from months m left join completed x on x.m=m.m left join invoices i on i.m=m.m left join payments p on p.m=m.m left join expenses e on e.m=m.m left join fuel f on f.m=m.m left join payroll_approved a on a.m=m.m left join payroll_paid q on q.m=m.m order by m.m;end$$;
revoke all on function public.list_verified_year_end_records(integer)from public,anon;grant execute on function public.list_verified_year_end_records(integer)to authenticated;commit;
